import{_ as o,C as r,o as a,c as n,j as e,a as s,E as l,a6 as i}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"如果你想改变人生，你需要走极端","description":"","frontmatter":{"title":"如果你想改变人生，你需要走极端","originalTitle":"You Need To Be Extreme If You Want Your Life To Change","date":"2025-06-05","originalUrl":"https://thedankoe.com/letters/you-need-to-be-extreme-if-you-want-your-life-to-change/","minutes":15,"sourceHash":"0153e23f3b17d6369dfec4899eeb2ea8d780651286eb9ac9b957cd52023bd4dd","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-need-to-be-extreme-if-you-want-your-life-to-change/"}]]},"headers":[],"relativePath":"letters/you-need-to-be-extreme-if-you-want-your-life-to-change.md","filePath":"letters/you-need-to-be-extreme-if-you-want-your-life-to-change.md"}'),g={name:"letters/you-need-to-be-extreme-if-you-want-your-life-to-change.md"};function h(d,p,c,m,u,b){const t=r("ArticleMeta");return a(),n("div",null,[p[0]||(p[0]=e("h1",{id:"如果你想改变人生-你需要走极端",tabindex:"-1"},[s("如果你想改变人生，你需要走极端 "),e("a",{class:"header-anchor",href:"#如果你想改变人生-你需要走极端","aria-label":'Permalink to "如果你想改变人生，你需要走极端"'},"​")],-1)),l(t),p[1]||(p[1]=i('<p>我清楚地记得2021年我生日那个周末。</p><p>我的生意开始变得非常好。我正处于减重的尾声阶段（在疫情期间我增重了20-30磅）。我正在写我第一本书的第一稿。</p><p>临近我生日的那段时间，感觉每个周末都有一件“不能错过”的事情。</p><p>演唱会。和朋友聚会。诸如此类的事情。正常的生活。</p><p>而我正在取得很大的进展，休息一下应该没什么坏处。</p><p>于是我出去了。我喝酒了。熬夜了。饮食也放纵了。你能猜到结果——我在各方面取得的进展不仅停滞了，还迅速走了下坡路（多谢熵增）。</p><p>我的精神和体力大约需要4-5天才能恢复。而到那时候，又有另一个活动要参加了。我没法为我的书或生意好好思考，健身习惯也变得更难维持。</p><p>这很痛苦，但那种痛苦还没到极限。</p><p>几个月前，我和我的朋友们就计划好在我生日那天去西雅图。</p><p>我已经厌倦了毫无进展的状态，但那是我的生日啊。为什么不放松一下，找点乐子呢？一旦身处那样的环境，我似乎总能找到理由为自己每一个糟糕的决定开脱。</p><p>经历了一个整天晚起、在任何事情上都<strong>毫无</strong>进展、又远离家的周末之后，我彻底受够了。</p><p>我他妈的气死自己了。</p><p>因为当你把目标当作这个世界上最重要的事情时，它们会照出你做错的一切。这世上最痛苦的事情，就是眼看着那些目标逐渐淡出你的生活，被肤浅的享乐目标所取代。</p><p>我一回到家，就消失了。</p><p>我不回复任何人。我变得不可联系。任何形式的邀请都是自动拒绝。我做的每一个行动都感觉顺理成章。我<strong>想要</strong>自律。它给我带来了快乐。我的心智回来了。我的身体回来了。我的生活回来了。</p><p>我的整个世界在一瞬间改变了。</p><p>但为什么会这样呢？</p><h3 id="_1-走极端会改变你的大脑" tabindex="-1">1）走极端会改变你的大脑 <a class="header-anchor" href="#_1-走极端会改变你的大脑" aria-label="Permalink to &quot;1）走极端会改变你的大脑&quot;">​</a></h3><p>“一起放电的神经元，会连接在一起。”</p><p>这就是赫布定律（Hebb&#39;s Law），一句总结了与神经可塑性相关的神经心理学理论的名言。</p><p>神经可塑性，正如你可能知道的，是你的大脑通过在一生中形成新的神经连接来重新连接自身的能力。你的大脑不是固定和僵化的。它是一个动态网络，可以根据你的经历、想法和行动进行适应、学习和改变。</p><p>对改变人生这件事走极端，有助于加快这一过程。</p><p>人们常常喊着“坚持才是关键”，这确实没错，因为重复能通过持续的努力强化神经通路，但我们可以更进一步。</p><p>新奇和挑战能更大程度地刺激神经可塑性。</p><p>所以，当你按下开关、全力以赴追求一个目标时，你就把大脑置于一个能迅速适应的环境中，帮助那种状态成为你的<strong>新标准</strong>。</p><h3 id="_2-强度与执念创造出一种神经化学鸡尾酒" tabindex="-1">2）强度与执念创造出一种神经化学鸡尾酒 <a class="header-anchor" href="#_2-强度与执念创造出一种神经化学鸡尾酒" aria-label="Permalink to &quot;2）强度与执念创造出一种神经化学鸡尾酒&quot;">​</a></h3><p>大多数人陷入困境，是因为他们追求的是<strong>外在激励因素</strong>。</p><p>但当你在本文讨论的情境下投入执念时，你是被<strong>内在激励因素</strong>所驱动的。</p><p>这些因素相互叠加、相互强化，以一种能维持某种程度心流（一种最佳体验，或最令人愉悦的心理状态之一）的方式运作：</p><ul><li><strong>好奇心</strong>——探索未知、学习如何改变、填补知识空白的欲望。会因新奇感产生良好的多巴胺，以及去甲肾上腺素，后者能提高注意力，让你为学习做好准备。</li><li><strong>激情</strong>——你对能改变人生的道路建立起强烈的热情。会产生更多良好的多巴胺和去甲肾上腺素。</li><li><strong>目标感</strong>——一种你的行动正在为比自身更大的事物做贡献的感觉。达成目标会产生更多多巴胺，从而强化行为。血清素来自重要性和归属感。催产素来自连接感。</li><li><strong>自主性</strong>——主导自己生活和工作的欲望。控制自己的选择、行动和环境。同样会产生更多多巴胺，并降低皮质醇（那种被困在框框里的压力感），从而让你能进行创造性的决策。</li><li><strong>精通</strong>——学习和成长的过程本身就是奖赏。会产生可持续的良好多巴胺，让你保持在这场游戏中。</li></ul><p>当我们谈到在你有着不可否认的改变欲望时，该<strong>如何</strong>度过接下来的6个月时，你就会理解这些因素是如何发挥作用的。</p><h3 id="_3-你的心智会根据你所执念的东西来过滤现实" tabindex="-1">3）你的心智会根据你所执念的东西来过滤现实 <a class="header-anchor" href="#_3-你的心智会根据你所执念的东西来过滤现实" aria-label="Permalink to &quot;3）你的心智会根据你所执念的东西来过滤现实&quot;">​</a></h3><blockquote><p>一个自认为是“失败型人格”的人，即使机会实实在在地摆在他面前，也会不顾自己所有的良好意愿或意志力，找到某种方式让自己失败。一个自认为是不公正的受害者、“命该受苦”的人，总会找到某些情况来证实他的看法。</p><p>——马克斯韦尔·马尔茨（Maxwell Maltz）</p></blockquote><p>我们的心智是为生存而设计的。</p><p>但人类有趣的地方在于，我们不仅像动物那样试图保护和复制我们DNA中的信息，我们还试图保护和复制我们意识中的信息。</p><p>也就是说，当我们的身体，或者我们的<strong>身份认同</strong>受到威胁时，我们会感到受威胁。</p><p>从消极的一面来看，我们会注意到那些强化我们信念和世界观的信息，这常常导致我们对质疑我们宗教或政治信仰的人恶言相向。我们的身份认同感觉受到了威胁，大脑的应激反应发出那种信号，于是我们感到需要去“求生”。</p><p>从积极的一面来看，当你与自己执念的目标产生认同时，你会在环境中注意到能强化你正在成为的那个更高版本自我的机会。由于你的身份认同已经提升，它会试图在那个更高层次上生存下去，从而促使你去收集知识、采取行动来实现这一点。</p><p>由于我们的祖先生活在一个资源稀缺的环境中，当他们注意到某些有助于维持生存的东西时，比如灌木丛中的浆果或用来取火的木材，多巴胺就会涌入他们的大脑，提高他们的注意力。</p><p>如果我们借用控制论并将其应用于心灵（心智／灵魂），我们就能看到我们的心智对我们的目标有某种归位机制。我们的心智接受能帮助它的信息，拒绝无益的信息。你会毫不费力地被引导向你的目标。</p><p>总结一下，<strong>如果你对某个目标产生执念，宇宙就会给你提供实现它所需的资源，与你共谋。</strong></p><h2 id="进化从无序中创造出秩序" tabindex="-1">进化从无序中创造出秩序 <a class="header-anchor" href="#进化从无序中创造出秩序" aria-label="Permalink to &quot;进化从无序中创造出秩序&quot;">​</a></h2><p>热力学第二定律指出，所有自然过程都随着时间的推移趋向于更大的无序状态。</p><p>换句话说，熵会随时间增加，而熵是衡量一个系统中混乱、无序或随机程度的指标。</p><p>这催生了“时间之矢”、不可逆性和决定论等概念。</p><p>即时间是不可逆的，并朝着熵增的方向前进。</p><p>然而，这并非全貌。宇宙并不是朝着一个以火焰终结世界的死胡同前进。事实恰恰相反。</p><p>伊利亚·普里高津（Ilya Prigogine）在他的著作《确定性的终结》（The End of Uncertainty）中提出，这种“时间之矢”不仅仅是一种幻觉，而是现实本身的一个基本特征。当一个系统被推离平衡态足够远时，它会变得不稳定。</p><p>关键点在这里：这种不稳定性可以导致<strong>一种被称为“耗散结构”的新的、复杂的、有序模式的自发涌现。</strong></p><p>想象一大股水从水龙头流出。当它流向排水口时，会形成一个美丽的漩涡。那就是从混沌<strong>中</strong>产生的秩序。</p><p>对于喜欢深究的人，让我们再深入一点。</p><p>我喜欢用实际应用来绘制大格局的模式，因为在<strong>理论上</strong>，它们是你能找到的最接近真理的东西，而不会被困在某种方法或范式之中。</p><p>当我们以一种通用的方式思考宇宙时，我们会发现它是由<strong>整体—部分</strong>（whole-parts）构成的。</p><p>不仅仅是部分。也不仅仅是整体。是整体—部分。每一件<strong>事物</strong>既是自身的一个整体，又是另一个整体的一部分。一直往上，也一直往下。</p><p>原子是一个整体，也是分子的一部分。</p><p>分子是一个整体，也是细胞的一部分。</p><p>细胞是有机体的一部分。</p><p>有机体是环境的一部分。</p><p>字母 → 单词 → 句子 → 段落</p><p>物质 → 生命 → 心智 → 灵魂 → 精神</p><p>采集社会 → 园艺社会 → 农业社会 → 工业社会 → 信息社会</p><p>无限嵌套的层级，带着无限互联的连接。</p><p>随便挑一个你能看到、听到、触摸到、尝到、闻到或想到的东西，你都会意识到这一点。</p><p>现在，这些整体—部分有各种描述其特性和行为的原则，比如它们进行自我保存（能动性）、自我适应（共融性）、自我超越和自我消解的基本能力。如果你想更多地了解这些原则，我建议阅读肯·威尔伯（Ken Wilber）的《万物简史》（A Brief History of Everything）。这是我最喜欢的书之一，还有《整合心理学》（Integral Psychology），这本书现在正让我大开眼界。</p><p>这些整体—部分有一个特性我想重点谈谈，它与普里高津的论点有关联：</p><p><strong>进化从混沌中创造出秩序。</strong></p><p>随着物质的演进，生命涌现了。随着生命的演进，心智涌现了。</p><p>当任何事物变得更发达或更复杂时，一个包含这些复杂部分的结构、新的整体就会涌现出来。</p><p>请耐心听我把这一切串联起来。</p><p>当你把熵的概念应用到心灵上时，你就得到了心理熵（psychic entropy）。</p><p>换句话说，心智倾向于走向无序、随机、混沌等状态。</p><p>在你的个人生活中，当你到达感觉迷失，或者觉得你的生活正在陷入混乱的那个点时，<strong>你正被赋予了一个让更高版本的自我涌现出来的机会。</strong></p><p>正如我在生日那天对自己缺乏进展感到厌烦透了的故事所展示的那样，你需要走到<strong>失调与洞见</strong>的交叉路口。</p><p>一旦你充分体会到你所处的境地，你就会开始感觉自己像是被撕成了两半。</p><p>你身上较低层次的那一部分想要维持现状。</p><p>你身上较高层次的那一部分想要改变。</p><p>当你向更高层次倾斜时，洞见就会与你相遇。</p><p>那正是将你推向极端的临界点。</p><h2 id="消失3-6个月-专注于4个习惯" tabindex="-1">消失3-6个月，专注于4个习惯 <a class="header-anchor" href="#消失3-6个月-专注于4个习惯" aria-label="Permalink to &quot;消失3-6个月，专注于4个习惯&quot;">​</a></h2><blockquote><p>新知识会在你只是把你需要知道的东西记在心里时到来。持续把问题记在脑中，它就会屈服。人类的历史无疑证明了这一事实。一个人遇到一个问题，然后只是不断地琢磨那个问题，直到他或她解决它……这可能需要一周、一个月、一年、十年、一个世纪，或者一千年，但这个宇宙（Kosmos）似乎总会不断地给出解答。</p><p>——肯·威尔伯（Ken Wilber）</p></blockquote><p>僧侣模式。</p><p>我肯定你对它很熟悉。</p><p>这是一个在自我提升领域被谈论了十多年的概念，但最近由于它被常态化，已经变成了一个庸俗化的版本。每个人都谈论过它，正因为每个人都知道它，它常常被简化为一个肤浅的定义：“切断所有人，赚更多的钱。”</p><p>我们不打算这么做。</p><p>事实上，我们甚至不打算遵循“修行模式”（monk mode）原本的含义。</p><p>当马拉犁被发明出来后，自由人不再需要花那么多时间去寻找食物，因为食物已经变得充裕。这使得他们（历史上第一次）能够去追求专门的兴趣，比如写作、数学、帝国建设，以及——就我们的讨论而言——<em>沉思</em>，去思索自身的存在。</p><p>人们很快意识到，神性并非“在外面”或“在上面”与那些神话中的神明同在，而是“在内心”。不久之后，便迎来了“轴心时代”，革命性的精神和哲学思想在多个文明中同时涌现。古希腊的苏格拉底，印度的乔达摩·佛陀，中国的老子。</p><p>这一在精神性上的突破，具体来说是“纯粹上升式”的。</p><p>上升式灵性，或称苦行主义（asceticism），是一种将显现世界视为邪恶的观点。既然天国是“在内心”而非“在外面”，那么金钱、性、食物和享乐便被妖魔化了。</p><p><em>真正的</em>修行模式正是如此：一段专注于上升之路与自我实现的时期。</p><p>问题是，大多数不拘泥于教条的人会意识到，灵性只是拼图的一部分。它非常重要，但如果把解决你所有问题的答案都归结为沉思，那就和把一切归结为原子、金钱，或者<em>仅仅是部分</em>一样糟糕。</p><p>相反，我们要做的是：为了通往更好的生活，消失一段高强度的时间。</p><p>一段你痴迷于解决某个问题、直到问题被解决为止的时期。而在这里，我们的问题是：我们想要改变整个生活。</p><p>我们需要的，如果你愿意这么说的话，是一种全面的“修行模式”。</p><p>这分为两个部分：防守和进攻。</p><h3 id="防守——清除干扰" tabindex="-1">防守——清除干扰 <a class="header-anchor" href="#防守——清除干扰" aria-label="Permalink to &quot;防守——清除干扰&quot;">​</a></h3><p>专注不仅仅适用于工作。</p><p>干扰也不仅仅是那些把你从工作中拉走的通知。</p><p>“消失”这件事的全部意义，在于在系统中制造一个漏洞。一夜之间改变你的身份。摆脱那些拖累你、耗尽你能量的螃蟹和寄生虫——那部分本该用于做出通往更好未来的选择的能量。</p><p>为了做到极致，一次性改变所有事情，比一次只改变一件事情要容易得多。</p><p>把创可贴一下子撕掉。</p><p>停止回应那些只索取从不给予的人。</p><p>任何把你拉离目标的邀约，都应该得到一个自动而坚决的“不”。</p><p>每一个不利于你的坏习惯，明天就停止，没有例外。</p><p>选择你自己的限制，是一种令人难以置信的美好感觉。</p><p>摆脱那些将你的注意力从你能做到的最高之善中分裂出来的东西。</p><p>琐碎的干扰——比如念头、担忧、饥饿，或者工作相关的视觉杂乱——会在接下来的步骤中，随着你对这条道路的投入而得到解决。真正全然投入的标志，是那些干扰甚至都没有机会在你的注意力中显现。</p><h3 id="进攻——4个专注习惯" tabindex="-1">进攻——4个专注习惯 <a class="header-anchor" href="#进攻——4个专注习惯" aria-label="Permalink to &quot;进攻——4个专注习惯&quot;">​</a></h3><p>美好的人生源自对善、真、美的追求。</p><p>对真理的追求。</p><p><strong>善</strong>是主体间的真理，是对人类或社群而言的善——做正确的事。</p><p><strong>真</strong>是客观的真理，存在于科学研究之中（科学得出数据，数据即经验，经验是身体的、心理的，<em>也是</em>精神的）——学习并理解事物真正的样貌。这是一个过程。</p><p><strong>美</strong>是主观的真理，属于美学的领域——去留意并<em>创造</em>你周围的美。</p><p>当我们把这种追求应用到自己的个人生活中，而不是社会变革或某种系统性问题时，我们的注意力便转向了我们的日常习惯。</p><p>有很多种不同的习惯变体可以满足这些要求，但我想给出一个清晰而简单的建议。</p><p>以下是接下来6个月里，你要“消失”并<em>每天</em>去做的事情。</p><p>一个项目。</p><p>一本书。</p><p>一次冥想。</p><p>一次锻炼。</p><p><strong>1）一个项目</strong></p><p>工作是生活中必要的一部分，它为休息与闲适带来了对比。</p><p>但大多数人从事的是他们厌恶的工作，于是他们把孩子和洗澡水一起扔掉，指望着自己永远不必再工作。这是一种妄想。你不会在永久的假期和休息状态中感到幸福。更糟的是，普通人对休息的理解，是以享乐的形式进行自我毁灭，用它来麻痹为别人设定的目标而工作所带来的痛苦。</p><p><em>选择一个能作为你想要的生活的构建模块的项目。</em></p><p>这可以是任何事情。</p><p>一个能引向独立工作的创意项目。</p><p>一个能带来职业转变的作品集项目。</p><p>大多数情况下，考虑到AI的现状，我建议你至少<em>尝试</em>某种形式的创业，因为如果你是一个能主动适应、躲开被取代命运的<a href="https://thedankoe.substack.com/p/main-character-energy-mce" target="_blank" rel="noreferrer">高能动性</a>个体，你就不会被取代。</p><p>因为你正在尝试把善、真、美带入你的工作之中。而当别人把工作分配给你时，你无法控制这一点。</p><p>你的工作，以及推动你走向那份工作的项目，是<em>善</em>的一种体现。创业是一门在他人生活中解决问题的艺术。这是你通过履行一种能改善他们生活的角色，为一小群人所做的贡献。如果你能通过基于直接经验来构建解决方案，融入<em>真</em>，并通过表达你人格的深处来融入<em>美</em>，那你就走在正确的道路上。</p><p><strong>每天一小时的深度工作</strong>，投入到一个能够改变你职业生涯的项目上。</p><p>把它排进你的日程表。</p><p>不像工作的工作，正是世界所需要的（善）、你所拥有的经验（真）、以及你深切关心的事物（美）三者的交汇点。</p><p>当工作做得对的时候，它就等同于生活本身。</p><p>它是你所做的一切事情的中心支柱。</p><p><strong>2）一本书</strong></p><p>你必定会在6个月结束之前很久就读完一本书。</p><p>你可以多读一些，但说“两本书”就会破坏一切以“一”开头的那种乐趣。</p><p>如果你想改变你的生活，你就需要相应的知识。</p><p>你需要学校无法提供、或者从未提供过的教育。</p><p>你需要让自己的思维沉浸在那些已经活出了你想要的生活的人的思想之中。</p><p>这很简单。</p><p>一本书。</p><p>每天30分钟。</p><p>仅仅因为好奇而去学习新东西，正是<em>真</em>的一个绝佳体现。</p><p>而且，正如你会发现的那样，探索这一简单行为本身会带来新颖的想法，从而推动进步。</p><p><strong>3）一次冥想</strong></p><p>工作可以是美的、灵性的，但它无法完全替代一种维系你与现实之间连接的习惯。</p><p>我所说的冥想，并不是指坐在一个黑暗的房间里，让念头流过——尽管那也是一条完全可行的路径。</p><p>在我看来，冥想，是一种生活方式。</p><p>一种透过惊奇与感恩的镜片去感知世界的方式，去留意你周围那些令人惊叹的事物——当我们处于压力和狭隘思维中时，这些事物往往会被一扫而过。</p><p>在这个意义上，冥想的目的是去留意<em>深度</em>。</p><p>去逃离浅薄生活的陷阱。</p><p>每天至少10分钟，尝试通过你的感官，去细致地留意现实。</p><p>去散步，只专注于双脚触地的感觉。</p><p>凝视一棵树，去留意那些你以前从未注意过的精微细节。</p><p>在和所爱之人交谈时，深深地去倾听。不要只留意言语，去留意语调、表情，一切。</p><p>连续凝视你的手10分钟（是的，我是认真的），让你的思绪在细节中越走越深。</p><p>在洗碗时感受手上的水。这一生里，至少一次真正地去感受你所触碰的一切。倾听那寂静的声音，或远处车辆的声音。去细细品味哪怕最平淡无奇的食物中那精微的气味。</p><p>不要把这件事想得太复杂。</p><p><strong>4）一次锻炼</strong></p><blockquote><p>没有人有权在身体训练这件事上做个门外汉。一个人若在未曾见识过自己身体所能拥有的美与力量之前就衰老下去，那是一种羞耻。</p><p>——苏格拉底</p></blockquote><p>回到现实是由“整体—部分”（whole-parts）构成这个话题：</p><p>另一个重要的原则是：摧毁较低层级，对较高层级而言同样是自我毁灭。</p><p>如果我们毁灭地球，人类也会随之毁灭。</p><p>如果癌细胞侵入有机体，整个有机体就会生病。</p><p>如果你从一段话中抽掉一句话，这段话往往就失去了它的意义。</p><p>你活在你的身体里。</p><p>去了解它、训练它、以尊重的态度对待它，应该被视为你的全职工作，因为除此之外的任何做法，都是彻头彻尾的自我毁灭。</p><p>不仅如此，健康的缺失还会向上波及，影响你思维的创造力、你工作的质量，以及你人际关系中连接的深度。一切都是相互关联的。</p><p>投入到一次锻炼中。</p><p>无论你最想做什么。</p><p>找一个跑步计划、力量训练计划、普拉提课程，无论是什么都行。</p><p>重点在于，去关注那个让你每一天都能存在于此的身体。</p><p>4个简单的习惯，可以彻底改变你的生活。</p><p>4个简单的习惯，可以让你与善、真、美保持一致。</p><p>4个简单的习惯，可以通过好奇心、热情、目的感、自主性和精熟，带你进入更高层次的愉悦状态。</p><p>对病态的生活方式感到厌倦吧。</p><p>允许自己走向极致。</p><p>消失，然后带着一个连自己都认不出的自己归来。</p><p>——丹（Dan）</p><p>6月16日，“30天打造盈利个人品牌”挑战正式开始。</p><p>如果你想了解现代创业之路，把你的兴趣转化为一份充实事业的基石，并在接下来的30天里，每天有30到60分钟跟着一个有引导的项目去实践，<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">可以考虑在这里报名。</a></p><p>如果你还没准备好，可以考虑阅读<a href="https://thedankoe.substack.com/p/how-to-build-a-better-personal-brand" target="_blank" rel="noreferrer">上周的信</a>，了解个人品牌是如何改变我的人生的。</p><hr><p><a href="/en/letters/you-need-to-be-extreme-if-you-want-your-life-to-change">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',186))])}const k=o(g,[["render",h]]);export{_ as __pageData,k as default};
